-- ============================================================
-- Instinctive Fire needs a family flag before anything can modify it
-- ============================================================
--
-- 1462 was repurposed into Instinctive Fire by woa_2026_08_11_03.sql with
-- SpellFamilyName 9 but SpellFamilyFlags 0/0/0.  SpellInfo::IsAffectedBySpellMod
-- matches `spellmod->mask & spellInfo->SpellFamilyFlags`, so a spell with no
-- flags can never be the target of an ADD_FLAT/PCT_MODIFIER -- 200757's charge
-- would sit there forever and never be consumed, with no error to say why.
--
-- Bit 21 of the THIRD mask word is used.  It was picked by scanning every
-- family-9 spell in Spell.dbc: words 0 and 1 are effectively exhausted
-- (0xffffffff and 0xffffffbf), word 2 has bits 21-30 free, and no family-9
-- EffectSpellClassMaskC in the entire DBC sets bit 21 -- so nothing existing
-- starts modifying Instinctive Fire as a side effect of this.
--
-- Single-column change to an existing custom spell: UPDATE, never a 234-column
-- re-INSERT that would revert everything else woa_2026_08_11_03.sql set.
UPDATE `alonecraft_spell_dbc` SET `SpellFamilyFlags2` = 2097152 WHERE `ID` = 1462;


-- ============================================================
-- Invigoration: wiring
-- ============================================================
--
-- TODO.md: "Invigoration (0, 7): When your pet scores a critical hit with a
-- special ability, you have a 100% chance to instantly regenerate 1% mana and
-- the cooldown on Instinctive Fire is reset and costs no mana. (2 ranks)"
-- Mana is 1% at rank 1 and 2% at rank 2.
--
-- Retail's plumbing is a dead end and is NOT extended.  Core's
-- spell_hun_invigoration (spell_hunter.cpp:561) is a SpellScript on 53412, and
-- nothing anywhere in src/server/ ever casts 53412 -- the id appears in that
-- comment and nowhere else.  There is also no spell_pet_auras row for the
-- talent.  The talent has simply never functioned on this core, which is why it
-- is rebuilt from the pet side rather than patched.
--
-- Effect1 becomes the carrier (the retail 50/100% chance moves into
-- spell_proc.Chance, which is 100 -- the requirement asks for certainty and puts
-- the rank scaling in the mana instead).  Effect2 carries the mana percentage.
DELETE FROM `spell_pet_auras` WHERE `spell` IN (53252, 53253);
INSERT INTO `spell_pet_auras` (`spell`, `effectId`, `pet`, `aura`) VALUES
(53252, 0, 0, 200756),
(53253, 0, 0, 200756);

-- ProcFlags 65552 = 0x10010
--   0x00000010 PROC_FLAG_DONE_SPELL_MELEE_DMG_CLASS
--   0x00010000 PROC_FLAG_DONE_SPELL_MAGIC_DMG_CLASS_NEG
-- "a special ability" means exactly this: Claw/Bite/Gore are DamageClass MELEE
-- and the elemental abilities (Lightning Breath, Fire Breath) are MAGIC.  White
-- swings are PROC_FLAG_DONE_MELEE_AUTO_ATTACK (0x4) and are deliberately absent.
--
-- HitMask 2 = PROC_HIT_CRITICAL.
--
-- Cooldown 6000 is the balance lever.  100% chance with no ICD on a pet that
-- crits several times per 8 seconds does not "reset" an 8-second cooldown, it
-- deletes it.  At 6s the reset is frequent and still a proc.
DELETE FROM `spell_proc` WHERE `SpellId` = 200756;
INSERT INTO `spell_proc` (`SpellId`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `ProcFlags`, `SpellTypeMask`, `SpellPhaseMask`, `HitMask`, `AttributesMask`, `DisableEffectsMask`, `ProcsPerMinute`, `Chance`, `Cooldown`, `Charges`) VALUES
(200756, 0, 0, 0, 0, 0, 65552, 0, 2, 2, 0, 0, 0, 100, 6000, 0);

-- 200757 uses the ProcCharges pattern: ADD_PCT_MODIFIER on SPELLMOD_COST (14)
-- at -100%, family 9, class mask C bit 21 = Instinctive Fire, ProcCharges 1.
-- The engine consumes the charge itself when the modifier matches a cast, so
-- there is no spell_proc row and no teardown code.
--
-- Core's own 53398 is NOT reused for the mana.  It is SPELL_EFFECT_ENERGIZE_PCT
-- with EffectImplicitTargetA1 = 1 (caster), and the caster here is the PET --
-- it would refill the pet's non-existent mana bar.  200744 (from
-- woa_2026_08_11_08.sql) is cast by the owner on itself with a flat amount the
-- script computes, which sidesteps the whole targeting question.  Same class of
-- trap as WarlockDemonPets.cpp:532.
DELETE FROM `spell_script_names` WHERE `spell_id` = 200756;
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`) VALUES
(200756, 'spell_hun_invigoration_pet');
